/** UC1-RESUME-MIRROR tests — TS mirror of hermes UC1Handoff.resume() (8871dda).
 *
 * Error reason strings are asserted byte-for-byte (the mirror law); stderr
 * tails that embed host/tool output are prefix-pinned only. The valid-snapshot
 * test deep-equals the committed golden fixture
 * `packages/opencode/test/fixtures/uc1-resume-golden.json`, generated by the
 * hermes reference — same fixture, same fields, as the hermes
 * `UC1ResumeGoldenParityTests` (09-plugin-parity.md §4).
 *
 * Fixture discipline: snapshots are built with cwd=repo root and the RELATIVE
 * trace argv `corpus/m1/session-healthy.jsonl` — manifest.yaml/llms.txt embed
 * the trace argv string, so relative keeps artifact bytes host-independent
 * (probed 2026-10-25). Requires the release binaries + the zstd CLI.
 */

import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { test } from "node:test";

import type { ResumeResult } from "../src/uc1-resume.ts";
import { resumeVerify, rustBinDir, snapshotDigest } from "../src/uc1-resume.ts";

const REPO_ROOT = fileURLToPath(new URL("../../..", import.meta.url));
const ANCHOR = "corpus/m1/session-healthy.jsonl"; // relative argv (fixture discipline)

const GOLDEN_PATH = join(REPO_ROOT, "packages/opencode/test/fixtures/uc1-resume-golden.json");
const GOLDEN = JSON.parse(readFileSync(GOLDEN_PATH, "utf8")) as {
  snapTurn: number;
  verified: boolean;
  reason: string;
  snapshotDigest: string;
  artifactNames: string[];
};

function freshTmp(label: string): string {
  return mkdtempSync(join(tmpdir(), `ctxvm-b3-${label}-`));
}

function baseName(path: string): string {
  const parts = path.split("/");
  return parts[parts.length - 1] ?? path;
}

function buildGoldenSnapshot(dir: string): void {
  const bin = rustBinDir();
  assert.ok(bin, "release binaries not built — run the cargo build gate");
  const proc = spawnSync(
    join(bin, "export"),
    [ANCHOR, "--turn", "0", "--output", dir, "--odps"],
    { cwd: REPO_ROOT, encoding: "utf8" },
  );
  assert.equal(proc.status, 0, `export failed: ${proc.stderr}`);
}

test("missing dir / empty dir / unparseable turn — reason law byte-for-byte", () => {
  const missing = join(tmpdir(), "ctxvm-b3-nonexistent-resume-snapshot");
  rmSync(missing, { force: true, recursive: true });
  const missingRes: ResumeResult = resumeVerify(missing);
  assert.deepEqual(missingRes, {
    exit_code: 2,
    verified: false,
    reason: `snapshot dir not found: ${missing}`,
    evidence: {},
  });

  const empty = freshTmp("empty");
  assert.deepEqual(resumeVerify(empty), {
    exit_code: 2,
    verified: false,
    reason: `no trace-*.jsonl.zst in ${empty}`,
    evidence: {},
  });

  const badTurn = freshTmp("badturn");
  writeFileSync(join(badTurn, "trace-x.jsonl.zst"), "not a real zstd frame");
  assert.deepEqual(resumeVerify(badTurn), {
    exit_code: 2,
    verified: false,
    reason: "cannot parse turn from trace-x.jsonl.zst",
    evidence: {},
  });
});

test("zstd decompress failure → loud unverified, evidence {turn, snapshot} (prefix pin)", () => {
  const dir = freshTmp("zstdfail");
  writeFileSync(join(dir, "trace-0.jsonl.zst"), "not a real zstd frame");
  const res = resumeVerify(dir);
  assert.equal(res.exit_code, 2);
  assert.equal(res.verified, false);
  assert.match(res.reason, /^zstd decompress failed: /);
  assert.deepEqual(res.evidence, { turn: 0, snapshot: dir });
});

test("replay failure → reason law 'replay exit N: <stderr>' (prefix pin)", () => {
  const dir = freshTmp("replayfail");
  const junk = join(dir, "not-xCABI.jsonl");
  writeFileSync(junk, "this is not xCABI JSONL\n");
  const packed = spawnSync("zstd", ["-f", "-q", junk, "-o", join(dir, "trace-0.jsonl.zst")], {
    encoding: "utf8",
  });
  assert.equal(packed.status, 0, packed.stderr);
  const res = resumeVerify(dir);
  assert.equal(res.verified, false);
  assert.match(res.reason, /^replay exit \d+: /);
  assert.deepEqual(res.evidence, { turn: 0, snapshot: dir });
});

test("valid snapshot → verified; deep-equals the hermes-generated golden fixture", () => {
  const dir = freshTmp("golden");
  buildGoldenSnapshot(dir);
  const res = resumeVerify(dir);
  assert.equal(res.verified, GOLDEN.verified);
  assert.equal(res.exit_code, 0);
  assert.equal(res.reason, GOLDEN.reason);
  const ev = res.evidence;
  assert.equal(ev.snapshot, dir);
  assert.equal(ev.snapshotDigest, GOLDEN.snapshotDigest);
  assert.equal(ev.snapTurn, GOLDEN.snapTurn);
  assert.equal(ev.turn, GOLDEN.snapTurn);
  assert.deepEqual((ev.artifacts ?? []).map(baseName).sort(), GOLDEN.artifactNames);
});

test("snapshotDigest — checksums-hex path and name+bytes fallback mirrored exactly", () => {
  // checksums.sha256 present: hex strings only, sorted by filename.
  const dir = freshTmp("digest");
  writeFileSync(join(dir, "b.artifact"), "B");
  writeFileSync(join(dir, "a.artifact"), "AA");
  writeFileSync(join(dir, "checksums.sha256"), "def0  b.artifact\nabc0  a.artifact\n");
  const h = createHash("sha256");
  h.update("abc0"); // a.artifact first (sorted by name)
  h.update("def0");
  assert.equal(snapshotDigest(dir), "sha256:" + h.digest("hex"));

  // checksums.sha256 absent: sha256 over name||bytes of every other artifact.
  const fallback = freshTmp("digestfallback");
  writeFileSync(join(fallback, "b.bin"), "\x02\x01");
  writeFileSync(join(fallback, "a.bin"), "hello");
  const hf = createHash("sha256");
  hf.update("a.bin");
  hf.update(readFileSync(join(fallback, "a.bin")));
  hf.update("b.bin");
  hf.update(readFileSync(join(fallback, "b.bin")));
  assert.equal(snapshotDigest(fallback), "sha256:" + hf.digest("hex"));
});
